            anomaly_rows.append({
                "column": "deposits",
                "row_index": int(idx),
                "value": ov,
                "expected_range": expected_range_str,
                "severity": sev,
                "explanation": f"deposits value {ov:.2f} lies outside expected range {expected_range_str}"
            })

