    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    dep = df['deposits'].dropna()
    skew_val = float(dep.skew())

    if abs(skew_val) > 2:
        shift = max(0, -dep.min() + 1e-9)
        dep_t = np.log1p(dep + shift)
    else:
        shift = 0.0
        dep_t = dep

    q1 = dep_t.quantile(0.25)
    q3 = dep_t.quantile(0.75)
    iqr = q3 - q1

    lo_ext = q1 - 3 * iqr
    hi_ext = q3 + 3 * iqr

    lo_4 = q1 - 4 * iqr
    hi_4 = q3 + 4 * iqr
    lo_5 = q1 - 5 * iqr
    hi_5 = q3 + 5 * iqr

    mask_ext = (dep_t < lo_ext) | (dep_t > hi_ext)
    frac_flagged = mask_ext.sum() / len(dep_t)

    anomalies_out = []

    if frac_flagged > 0.05:
        anomalies_out.append({
            "column": "deposits",
            "row_index": None,
            "value": None,
            "expected_range": "heavy-tailed distribution",
            "severity": "low",
            "explanation": "deposits is heavy-tailed; more than 5% of values fall outside the extreme IQR boundary — column skipped for individual flagging"
        })
    else:
        flagged_idx = dep_t[mask_ext].index
        flagged_idx = flagged_idx[:25]

        if abs(skew_val) > 2:
            lo_orig = float(np.expm1(lo_ext) - shift)
            hi_orig = float(np.expm1(hi_ext) - shift)
        else:
            lo_orig = float(lo_ext)
            hi_orig = float(hi_ext)

        expected_range_str = f"{lo_orig:.2f} to {hi_orig:.2f} USD"

        for idx in flagged_idx:
            raw_val = float(df.loc[idx, 'deposits'])
            t_val = dep_t.loc[idx]

            if t_val > hi_5 or t_val < lo_5:
                sev = "critical"
            elif t_val > hi_4 or t_val < lo_4:
                sev = "high"
            else:
                sev = "medium"

            anomalies_out.append({
                "column": "deposits",
                "row_index": int(idx),
                "value": raw_val,
                "expected_range": expected_range_str,
                "severity": sev,
                "explanation": f"deposits value of {raw_val:.2f} USD lies outside the expected range of {expected_range_str}"
            })

    result['anomalies'] = anomalies_out
    result['assumptions'] = [
        "Anomaly detection applied to deposits column only (target metric).",
        f"Skewness of deposits is {skew_val:.3f}; log1p transform {'applied' if abs(skew_val) > 2 else 'not applied'}.",
        "Extreme boundary defined as Q1 - 3×IQR and Q3 + 3×IQR (in transform space).",
        "Columns flagging >5% of rows as extreme are treated as heavy-tailed and not individually flagged.",
        "balance excluded from anomaly detection per task scope (unusual deposits only)."
    ]

