    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df['As Of Date'] = pd.to_datetime(df['As Of Date'])
    df['Origination Date'] = pd.to_datetime(df['Origination Date'])

    closed_statuses = [
        'pending', 'declined', 'failed', 'rejected',
        'charged off', 'charged_off', 'charged-off', 'charge off',
        'written off', 'written_off', 'write off',
        'paid off', 'paid_off', 'fully paid', 'closed'
    ]

    df['_status_lower'] = df['Loan Status'].str.lower().str.strip()

    # Latest snapshot per Loan ID (any kind)
    latest_any = df.sort_values('As Of Date').groupby('Loan ID').last().reset_index()

    # Keep only on-book rows (exclude closed/charged-off etc.)
    on_book = latest_any[~latest_any['_status_lower'].isin(closed_statuses)].copy()

    # NPL: dpd >= 90 or status in non-accrual/nonaccrual/default/defaulted
    npl_statuses = ['non-accrual', 'nonaccrual', 'non_accrual', 'default', 'defaulted']
    on_book['_is_npl'] = (
        (on_book['Days Past Due'] >= 90) |
        (on_book['_status_lower'].isin(npl_statuses))
    )

    # NPL ratio by Product
    product_groups = on_book.groupby('Product')
    npl_results = []
    for prod, grp in product_groups:
        total_bal = grp['Outstanding Principal'].sum()
        npl_bal = grp.loc[grp['_is_npl'], 'Outstanding Principal'].sum()
        ratio = float(npl_bal / total_bal) if total_bal > 0 else 0.0
        npl_results.append({"name": str(prod), "value": round(ratio, 6)})

    npl_results_sorted = sorted(npl_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "npl_ratio",
        "results": npl_results_sorted
    })

    # Overall NPL ratio
    total_bal_all = on_book['Outstanding Principal'].sum()
    npl_bal_all = on_book.loc[on_book['_is_npl'], 'Outstanding Principal'].sum()
    overall_npl = float(npl_bal_all / total_bal_all) if total_bal_all > 0 else 0.0

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "npl_ratio_overall",
        "results": [{"name": "All Products", "value": round(overall_npl, 6)}]
    })

    # Outstanding Principal sum by Product (on-book)
    bal_by_product = on_book.groupby('Product')['Outstanding Principal'].sum().reset_index()
    bal_by_product = bal_by_product.nlargest(10, 'Outstanding Principal')
    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "sum",
        "label": None,
        "results": [
            {"name": str(row['Product']), "value": float(row['Outstanding Principal'])}
            for _, row in bal_by_product.iterrows()
        ]
    })

    # Count of NPL loans by Product
    npl_count_results = []
    for prod, grp in product_groups:
        npl_count = int(grp['_is_npl'].sum())
        total_count = len(grp)
        npl_count_results.append({
            "name": str(prod),
            "value": float(npl_count)
        })

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Loan ID",
        "aggregation": "count",
        "label": "npl_loan_count",
        "results": sorted(npl_count_results, key=lambda x: x['value'], reverse=True)
    })

    result['assumptions'].append(
        "NPL defined as: Days Past Due >= 90 OR Loan Status in [non-accrual, nonaccrual, default, defaulted]."
    )
    result['assumptions'].append(
        "Balance uses each Loan ID's latest snapshot (any row kind); closed/charged-off/paid-off accounts excluded from on-book pool."
    )
    result['assumptions'].append(
        f"On-book loans used for NPL ratio: {len(on_book)} of {len(latest_any)} unique Loan IDs after excluding closed statuses."
    )
    result['assumptions'].append(
        "106 rows flagged as 'cancel' by row_kind; latest-snapshot logic applied across all row kinds before filtering."
    )

except Exception as e:
