import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Filter to 'sale' kind rows for balance analysis
    df_sale = df[df['row_kind'] == 'sale'].copy()

    # Per the semantic layer: per period take each Loan ID's last value (by As Of Date), then sum
    # Since timeframe is full dataset, get each Loan ID's latest snapshot
    df_sale['As Of Date'] = pd.to_datetime(df_sale['As Of Date'])
    latest_per_loan = df_sale.sort_values('As Of Date').groupby('Loan ID').last().reset_index()

    # avg_balance per account by branch: Total balance / open accounts
    branch_groups = latest_per_loan.groupby('Branch')

    branch_results = []
    for branch_name, grp in branch_groups:
        total_balance = grp['Outstanding Principal'].sum()
        open_accounts = len(grp)
        avg_bal = total_balance / open_accounts if open_accounts > 0 else 0.0
        branch_results.append({"name": str(branch_name), "value": round(float(avg_bal), 4)})

    # Sort by count descending, top 10
    branch_count = latest_per_loan.groupby('Branch').size().reset_index(name='cnt')
    top10_branches = branch_count.nlargest(10, 'cnt')['Branch'].tolist()
    branch_results_top10 = [r for r in branch_results if r['name'] in top10_branches]
    branch_results_top10 = sorted(branch_results_top10, key=lambda x: -next(
        (row['cnt'] for _, row in branch_count.iterrows() if row['Branch'] == x['name']), 0
    ))

    result['segments'].append({
        "segment_column": "Branch",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "avg_balance_per_loan",
        "results": branch_results_top10
    })

    result['assumptions'].append(
        "avg_balance_per_loan = sum(Outstanding Principal) / count(open loans) per branch, "
        "using each Loan ID's latest As Of Date snapshot, sale-kind rows only."
    )
    result['assumptions'].append(
        "Open accounts: rows with row_kind='sale' after taking each Loan ID's last row of any kind."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Branch",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "avg_balance_per_loan",
        "results": [{"name": "error", "value": 0.0}]
    })
    result['assumptions'].append(f"Segmentation error: {str(e)}")

