                _yearly.append((_col, _y, int(_frame.loc[_pair, _col].notna().sum())))
            return round(float((_tot.iloc[-1] / _tot.iloc[-2] - 1) * 100), 2), _n
        for _c in _targets:
            _jobs = [(None, df)]
