    df['As Of Date'] = pd.to_datetime(df['As Of Date'])
    df['Origination Date'] = pd.to_datetime(df['Origination Date'])

    closed_statuses = [
        'pending', 'declined', 'failed', 'rejected',
        'charged off', 'charged_off', 'charged-off', 'charge off',
        'written off', 'written_off', 'write off',
        'paid off', 'paid_off', 'fully paid', 'closed'
    ]
    df['_status_lower'] = df['Loan Status'].str.lower().str.strip()

    # Latest snapshot per Loan ID (any kind)
    latest_any = df.sort_values('As Of Date').groupby('Loan ID').last().reset_index()

    # Keep only on-book rows (exclude closed statuses)
    on_book = latest_any[~latest_any['_status_lower'].isin(closed_statuses)].copy()

    # Also filter by row_kind == 'sale' for balance
    on_book_sale = on_book[on_book['row_kind'] == 'sale'].copy()

    # Delinquency 30+ per product
    products = on_book_sale['Product'].dropna().unique()

    delinquency_results = []
    total_balance = on_book_sale['Outstanding Principal'].sum()
    total_delinq_balance = on_book_sale.loc[
        on_book_sale['Days Past Due'] >= 30, 'Outstanding Principal'
    ].sum()
    overall_delinq_rate = float(total_delinq_balance / total_balance) if total_balance > 0 else 0.0

    for prod in sorted(products):
        prod_df = on_book_sale[on_book_sale['Product'] == prod]
        prod_balance = prod_df['Outstanding Principal'].sum()
        prod_delinq = prod_df.loc[prod_df['Days Past Due'] >= 30, 'Outstanding Principal'].sum()
        rate = float(prod_delinq / prod_balance) if prod_balance > 0 else 0.0
        delinquency_results.append({"name": str(prod), "value": round(rate, 6)})

    delinquency_results_sorted = sorted(delinquency_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Days Past Due",
        "aggregation": "ratio",
        "label": "delinquency_30",
        "results": delinquency_results_sorted
    })

