    op_by_product = on_book_sale.groupby('Product')['Outstanding Principal'].sum().reset_index()
    op_by_product = op_by_product.sort_values('Outstanding Principal', ascending=False).head(10)
    op_results = [{"name": str(r['Product']), "value": float(r['Outstanding Principal'])}
                  for _, r in op_by_product.iterrows()]

